args.sql:
SELECT COUNT(*) as total, 
       COUNT(CASE WHEN UPPER(statustag) = 'CERTIFIED' AND decisionday IS NOT NULL THEN 1 END) as approved_with_decision
FROM cases;

SELECT visacls as visa_class, AVG(CAST(decisionday AS date) - CAST(recvday AS date))::numeric(10,2) as average_processing_time_days
FROM cases
GROUP BY visacls;

SELECT visacls, COUNT(*), AVG(CAST(decisionday AS date) - CAST(recvday AS date))::numeric(10,2) as avg_days
FROM cases
GROUP BY visacls;

